<script setup>
import {ref,reactive,watch,onMounted,onBeforeUnmount} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,session} from '../auth/api.js';import {createThread} from './thread.js';import {useCollection} from '../home/useCollection.js';import {LegacyState,LegacyPager,date} from '../../lib/legacy.js';import BusinessPage from '../../components/BusinessPage.vue';
const route=useRoute(),router=useRouter(),conversations=useCollection('/users/me/conversations',null,()=>({})),thread=createThread(api,undefined,reactive),state=thread.state,text=ref('');let timer;
async function select(id){if(state.pending&&!confirm('Tin nhắn chưa được xác nhận. Rời hội thoại này?'))return;await router.replace({query:{conversation:id}})}
async function poll(){if(document.hidden||!route.query.conversation)return;await thread.load();if(!state.error)try{await thread.markRead()}catch{state.error='Chưa cập nhật được trạng thái đã đọc.'}}
watch(()=>route.query.conversation,async id=>{thread.reset(typeof id==='string'?id:null);text.value='';await poll()},{immediate:true});
async function send(){if(await thread.send(text.value)){text.value='';await poll();await conversations.load(conversations.page)}}
onMounted(()=>timer=setInterval(poll,5000));onBeforeUnmount(()=>{clearInterval(timer);thread.dispose()});
</script><template><BusinessPage title="Tin nhắn"><p class="text-sm">Tin nhắn riêng giữa hai bên · cập nhật định kỳ bằng REST.</p><div class="grid gap-6 md:grid-cols-[280px_1fr]"><aside><LegacyState :state="conversations"/><p v-if="!conversations.busy&&!conversations.items.length">Chưa có hội thoại.</p><section v-for="c in conversations.items" :key="c.id"><button :aria-current="route.query.conversation===c.id?'page':undefined" @click="select(c.id)">Tin {{c.propertyId.slice(0,8)}} · {{c.unreadCount}} chưa đọc</button><p>{{date(c.updatedAt)}}</p></section><LegacyPager :state="conversations"/></aside><section v-if="route.query.conversation" aria-label="Nội dung hội thoại"><p v-if="state.error" role="alert">{{state.error}}</p><button :disabled="state.busy" @click="poll">{{state.busy?'Đang tải…':'Tải tin tiếp / cập nhật'}}</button><p v-if="!state.busy&&!state.items.length">Chưa có tin nhắn.</p><ol aria-live="polite"><li v-for="m in state.items" :key="m.id" class="my-3 rounded-xl bg-[#f1eee8] p-3"><strong>{{m.senderId===session.user?.id?'Bạn':'Người tham gia'}}</strong><p class="whitespace-pre-wrap">{{m.body}}</p><small>{{date(m.createdAt)}}</small></li></ol><p v-if="state.hasMore">Còn tin tiếp theo; bấm tải để xem.</p><form @submit.prevent="send"><label>Nội dung <textarea v-model="text" maxlength="4000" required :readonly="state.sendBusy"/></label><p v-if="state.pending">Tin trước chưa được server xác nhận. Thử lại cùng nội dung sẽ dùng cùng mã tin.</p><button :disabled="state.sendBusy||!text.trim()">{{state.sendBusy?'Đang gửi…':state.pending?'Thử gửi lại':'Gửi tin nhắn'}}</button></form></section><p v-else>Chọn một hội thoại hoặc mở “Nhắn tin” từ tin bất động sản.</p></div></BusinessPage></template>
